## Apps Script: Fuzzy Park Mapper

A few design decisions before the code:

**Similarity metric:** I'm using normalized Levenshtein (edit distance divided by max string length), which gives a 0–1 ratio where 1 is identical. It works well for your variants because most of them are abbreviations or minor typos rather than completely different words. The comparison runs on the stripped/lowercased key (non-letters removed), same as your formula approach, so "West-side" and "westside" are identical before the fuzzy step even kicks in.

**Thresholds I'd use for your data:**
- `>= 0.85` → High. At this level you're seeing at most 1–2 character differences on a typical park name. "Noth Park" vs "northpark" scores ~0.89. Safe to auto-accept.
- `0.60–0.84` → Low. Real matches exist here but so do coincidental near-matches. "central" vs "centralpark" scores ~0.70. Worth a human glance.
- `< 0.60` → Unmapped. The strings are too different to trust.
- **Ambiguous:** when two or more canonical parks both score `>= 0.60` and are within `0.10` of each other. This catches cases where the top match isn't clearly better than the second-best.

You can tighten the High threshold to `0.90` if you're seeing false positives, or loosen it to `0.80` if too many Low rows turn out to be obvious. I'd run it once at 0.85, audit the Low rows, and adjust from there.

---

## The Script

Paste this in **Extensions > Apps Script**, save, then run `fuzzyMapParks`.

```javascript
// ── Configuration ──────────────────────────────────────────────────────────
const CONFIG = {
  dataSheet:      "Clean",      // sheet with your volunteer data
  parkMapSheet:   "ParkMap",    // sheet with Key, Canonical columns
  rawCol:         6,            // column F (1-indexed) = PreferredPark
  canonicalCol:   10,           // column J = output canonical name
  confidenceCol:  11,           // column K = output confidence
  dataStartRow:   2,            // first data row (skip header)
  thresholdHigh:  0.85,
  thresholdLow:   0.60,
  ambigMargin:    0.10,         // if 2nd-best is within this of best, flag Ambiguous
};

// ── Main entry point ────────────────────────────────────────────────────────
function fuzzyMapParks() {
  const ss        = SpreadsheetApp.getActiveSpreadsheet();
  const dataSheet = ss.getSheetByName(CONFIG.dataSheet);
  const mapSheet  = ss.getSheetByName(CONFIG.parkMapSheet);

  if (!dataSheet) { SpreadsheetApp.getUi().alert(`Sheet "${CONFIG.dataSheet}" not found.`); return; }
  if (!mapSheet)  { SpreadsheetApp.getUi().alert(`Sheet "${CONFIG.parkMapSheet}" not found.`); return; }

  // Load ParkMap — expects columns: Key, Canonical (rows 2+, row 1 = header)
  const mapData = mapSheet.getDataRange().getValues();
  const parkMap = [];
  for (let i = 1; i < mapData.length; i++) {        // skip header row
    const key       = String(mapData[i][0]).trim();
    const canonical = String(mapData[i][1]).trim();
    if (key && canonical) parkMap.push({ key, canonical });
  }

  if (parkMap.length === 0) {
    SpreadsheetApp.getUi().alert("ParkMap is empty or has no data rows.");
    return;
  }

  // Load raw data column (single column read is fast)
  const lastRow  = dataSheet.getLastRow();
  const numRows  = lastRow - CONFIG.dataStartRow + 1;
  if (numRows <= 0) { SpreadsheetApp.getUi().alert("No data rows found."); return; }

  const rawRange = dataSheet.getRange(CONFIG.dataStartRow, CONFIG.rawCol, numRows, 1);
  const rawValues = rawRange.getValues();            // 2D array [[val], [val], ...]

  // Process each row and collect output — batch write at the end
  const canonicalOut  = [];
  const confidenceOut = [];

  for (let i = 0; i < rawValues.length; i++) {
    const raw = String(rawValues[i][0]).trim();

    if (!raw) {
      canonicalOut.push(["REVIEW"]);
      confidenceOut.push(["REVIEW"]);
      continue;
    }

    const key    = stripToKey(raw);
    const result = bestMatch(key, parkMap);

    canonicalOut.push([result.canonical]);
    confidenceOut.push([result.confidence]);
  }

  // ── Batch write (single Sheets API call each — much faster than per-row) ──
  dataSheet
    .getRange(CONFIG.dataStartRow, CONFIG.canonicalCol, numRows, 1)
    .setValues(canonicalOut);
  dataSheet
    .getRange(CONFIG.dataStartRow, CONFIG.confidenceCol, numRows, 1)
    .setValues(confidenceOut);

  SpreadsheetApp.getUi().alert(
    `Done. Processed ${numRows} rows against ${parkMap.length} park map entries.`
  );
}

// ── Matching logic ───────────────────────────────────────────────────────────

/**
 * Strips a raw value to the same key format used in ParkMap:
 * lowercase, non-letter characters removed.
 */
function stripToKey(raw) {
  return raw.toLowerCase().replace(/[^a-z]/g, "");
}

/**
 * Finds the best fuzzy match for `key` against all ParkMap entries.
 * Returns { canonical, confidence, score }.
 */
function bestMatch(key, parkMap) {
  let best       = { canonical: "", score: -1 };
  let secondBest = { canonical: "", score: -1 };

  // Group ParkMap by canonical so we compare key against each canonical once,
  // using the best-scoring key variant for that canonical.
  const canonicalScores = {};

  for (const entry of parkMap) {
    const score = similarity(key, entry.key);
    const canon = entry.canonical;

    if (canonicalScores[canon] === undefined || score > canonicalScores[canon]) {
      canonicalScores[canon] = score;
    }
  }

  // Find best and second-best canonical
  for (const [canon, score] of Object.entries(canonicalScores)) {
    if (score > best.score) {
      secondBest = { ...best };
      best       = { canonical: canon, score };
    } else if (score > secondBest.score) {
      secondBest = { canonical: canon, score };
    }
  }

  // Determine confidence
  let confidence;
  if (best.score < CONFIG.thresholdLow) {
    confidence = "Unmapped";
  } else if (
    secondBest.score >= CONFIG.thresholdLow &&
    (best.score - secondBest.score) <= CONFIG.ambigMargin
  ) {
    confidence = "Ambiguous";
  } else if (best.score >= CONFIG.thresholdHigh) {
    confidence = "High";
  } else {
    confidence = "Low";
  }

  return {
    canonical:  confidence === "Unmapped" ? raw => raw : best.canonical,
    confidence,
    score:      best.score,
  };
  // Note: for Unmapped rows, canonical is left as the raw value so you can
  // see what it was when reviewing. Change to "" if you prefer blanks.
}

// ── Levenshtein similarity (normalized) ─────────────────────────────────────

/**
 * Returns a 0–1 similarity ratio between two strings.
 * 1.0 = identical, 0.0 = completely different.
 * Uses iterative Levenshtein with two-row array (memory efficient).
 */
function similarity(a, b) {
  if (a === b) return 1.0;
  if (!a || !b) return 0.0;

  const maxLen = Math.max(a.length, b.length);
  const dist   = levenshtein(a, b);
  return 1 - dist / maxLen;
}

function levenshtein(a, b) {
  const m = a.length;
  const n = b.length;

  // Two-row approach: only keep previous and current rows
  let prev = Array.from({ length: n + 1 }, (_, j) => j);
  let curr = new Array(n + 1);

  for (let i = 1; i <= m; i++) {
    curr[0] = i;
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      curr[j] = Math.min(
        curr[j - 1] + 1,        // insertion
        prev[j] + 1,            // deletion
        prev[j - 1] + cost      // substitution
      );
    }
    [prev, curr] = [curr, prev]; // swap references, no allocation
  }

  return prev[n];
}
```

