## How to run it

1. **Extensions > Apps Script**, paste the whole thing, save (Ctrl+S).
2. Adjust the `CONFIG` block at the top — particularly `dataSheet`, `rawCol`, `canonicalCol`, `confidenceCol` to match your actual sheet and column layout.
3. Run `fuzzyMapParks`. First run will ask for permissions — that's normal.
4. Check columns J and K. Filter K to `Ambiguous`, `Low`, and `Unmapped` for review.

---

## Performance notes for 420 rows

The script as written runs in roughly 1–3 seconds for your dataset size. The two things that matter most for Sheets script performance are API call count and string work volume, so:

**Batch reads and writes** are already in place. The script reads the raw column in one call and writes both output columns in one call each, rather than reading/writing cell by cell. For 420 rows that difference is roughly 840 API calls avoided — at ~50ms per call that's the difference between under 3 seconds and over a minute.

**Levenshtein runs on stripped keys**, not raw strings, so the strings being compared are short (typically 6–15 characters). The two-row array approach keeps memory flat regardless of string length.

**ParkMap size matters more than row count.** Each data row is compared against every ParkMap entry. At your current ~16 entries that's about 6,700 comparisons total — trivial. If your ParkMap ever grows past ~200 entries you'd want to add an early-exit when `score === 1.0` (exact match found, no need to check further). I haven't added that since it's unnecessary overhead to reason about right now.

One thing to watch: if you re-run the script on the same sheet it will overwrite the J and K columns. That's intentional — it means you can add new ParkMap entries and re-run cleanly. Just don't manually edit J or K expecting those edits to survive a re-run.

```javascript
// ── Configuration ──────────────────────────────────────────────────────────
const CONFIG = {
  dataSheet:        "Clean",
  parkMapSheet:     "ParkMap",
  rawCol:           6,       // F  — raw PreferredPark
  canonicalCol:     10,      // J  — output: canonical name (or raw text if Unmapped)
  confidenceCol:    11,      // K  — output: High / Low / Unmapped / "Name (0.xx); Name (0.xx)"
  scoreCol:         12,      // L  — output: best similarity score (0–1)
  dataStartRow:     2,
  thresholdHigh:    0.85,
  thresholdLow:     0.60,
  ambigMargin:      0.10,
  processOnlyReview: false,  // true = skip rows where K is already filled and not REVIEW
};

// ── Main entry point ────────────────────────────────────────────────────────
function fuzzyMapParks() {
  const ss        = SpreadsheetApp.getActiveSpreadsheet();
  const dataSheet = ss.getSheetByName(CONFIG.dataSheet);
  const mapSheet  = ss.getSheetByName(CONFIG.parkMapSheet);

  if (!dataSheet) { SpreadsheetApp.getUi().alert(`Sheet "${CONFIG.dataSheet}" not found.`); return; }
  if (!mapSheet)  { SpreadsheetApp.getUi().alert(`Sheet "${CONFIG.parkMapSheet}" not found.`); return; }

  // ── Load ParkMap ──────────────────────────────────────────────────────────
  const mapData = mapSheet.getDataRange().getValues();
  const parkMap = [];
  for (let i = 1; i < mapData.length; i++) {
    const key       = String(mapData[i][0]).trim();
    const canonical = String(mapData[i][1]).trim();
    if (key && canonical) parkMap.push({ key, canonical });
  }
  if (parkMap.length === 0) {
    SpreadsheetApp.getUi().alert("ParkMap is empty or has no data rows.");
    return;
  }

  // ── Load data columns in one batch read ──────────────────────────────────
  // Read F (raw), J (existing canonical), K (existing confidence) together
  // to support processOnlyReview without extra API calls.
  const lastRow = dataSheet.getLastRow();
  const numRows = lastRow - CONFIG.dataStartRow + 1;
  if (numRows <= 0) { SpreadsheetApp.getUi().alert("No data rows found."); return; }

  // Read cols F, J, K in one getRange call (from rawCol to confidenceCol)
  const readStartCol = CONFIG.rawCol;                          // 6
  const readEndCol   = CONFIG.confidenceCol;                   // 11
  const readNumCols  = readEndCol - readStartCol + 1;          // 6 columns: F–K

  const blockRange  = dataSheet.getRange(
    CONFIG.dataStartRow, readStartCol, numRows, readNumCols
  );
  const blockValues = blockRange.getValues();

  // Column offsets within the block (0-indexed)
  const rawOffset        = CONFIG.rawCol        - readStartCol; // 0 → col F
  const canonicalOffset  = CONFIG.canonicalCol  - readStartCol; // 4 → col J
  const confidenceOffset = CONFIG.confidenceCol - readStartCol; // 5 → col K

  // ── Prepare output arrays (3 columns: J, K, L) ───────────────────────────
  const canonicalOut  = [];
  const confidenceOut = [];
  const scoreOut      = [];

  let processedCount = 0;
  let skippedCount   = 0;

  for (let i = 0; i < blockValues.length; i++) {
    const raw            = String(blockValues[i][rawOffset]).trim();
    const existingConf   = String(blockValues[i][confidenceOffset]).trim();

    // ── processOnlyReview gate ────────────────────────────────────────────
    if (CONFIG.processOnlyReview) {
      const alreadyFilled = existingConf !== "" &&
                            existingConf.toUpperCase() !== "REVIEW";
      if (alreadyFilled) {
        // Preserve whatever is already in J, K, L — read back existing values
        canonicalOut.push([blockValues[i][canonicalOffset]]);
        confidenceOut.push([existingConf]);
        scoreOut.push([""]);   // score column may not have been written yet;
                               // leave blank rather than overwrite a manual edit
        skippedCount++;
        continue;
      }
    }

    // ── Empty raw value ───────────────────────────────────────────────────
    if (!raw) {
      canonicalOut.push([""]);
      confidenceOut.push(["REVIEW"]);
      scoreOut.push([""]);
      continue;
    }

    // ── Fuzzy match ───────────────────────────────────────────────────────
    const key    = stripToKey(raw);
    const result = bestMatch(key, raw, parkMap);

    canonicalOut.push([result.canonical]);
    confidenceOut.push([result.confidence]);
    scoreOut.push([result.score === null ? "" : result.score]);
    processedCount++;
  }

  // ── Batch write all three output columns ─────────────────────────────────
  dataSheet
    .getRange(CONFIG.dataStartRow, CONFIG.canonicalCol, numRows, 1)
    .setValues(canonicalOut);
  dataSheet
    .getRange(CONFIG.dataStartRow, CONFIG.confidenceCol, numRows, 1)
    .setValues(confidenceOut);
  dataSheet
    .getRange(CONFIG.dataStartRow, CONFIG.scoreCol, numRows, 1)
    .setValues(scoreOut);

  // Format score column as 2 decimal places for readability
  dataSheet
    .getRange(CONFIG.dataStartRow, CONFIG.scoreCol, numRows, 1)
    .setNumberFormat("0.00");

  const skippedNote = CONFIG.processOnlyReview
    ? ` (${skippedCount} rows skipped — already mapped)`
    : "";
  SpreadsheetApp.getUi().alert(
    `Done. Processed ${processedCount} rows against ${parkMap.length} park map entries.${skippedNote}`
  );
}

// ── Matching logic ───────────────────────────────────────────────────────────

function stripToKey(raw) {
  return raw.toLowerCase().replace(/[^a-z]/g, "");
}

/**
 * Finds the best fuzzy match for `key` against all ParkMap entries.
 * `rawValue` is passed through so Unmapped rows can preserve the original text.
 *
 * Returns { canonical, confidence, score }
 *   canonical  — mapped name, raw text (Unmapped), or "" (empty input)
 *   confidence — "High" | "Low" | "Unmapped" | "Name (0.xx); Name (0.xx)"
 *   score      — best similarity score (0–1), or null for empty input
 */
function bestMatch(key, rawValue, parkMap) {

  // ── Score every canonical park (take best key-variant score per park) ────
  const canonicalScores = {};
  for (const entry of parkMap) {
    const score = similarity(key, entry.key);
    if (canonicalScores[entry.canonical] === undefined ||
        score > canonicalScores[entry.canonical]) {
      canonicalScores[entry.canonical] = score;
    }
  }

  // ── Sort by score descending to find best and second-best ────────────────
  const ranked = Object.entries(canonicalScores)
    .map(([canonical, score]) => ({ canonical, score }))
    .sort((a, b) => b.score - a.score);

  const best       = ranked[0];
  const secondBest = ranked[1] || null;

  // ── Unmapped ──────────────────────────────────────────────────────────────
  if (best.score < CONFIG.thresholdLow) {
    return {
      canonical:  rawValue,      // preserve raw text so reviewer can add it to ParkMap
      confidence: "Unmapped",
      score:      best.score,
    };
  }

  // ── Ambiguous — top two are both above thresholdLow and within ambigMargin ─
  if (
    secondBest &&
    secondBest.score >= CONFIG.thresholdLow &&
    (best.score - secondBest.score) <= CONFIG.ambigMargin
  ) {
    const ambigText =
      `${best.canonical} (${best.score.toFixed(2)}); ` +
      `${secondBest.canonical} (${secondBest.score.toFixed(2)})`;
    return {
      canonical:  best.canonical,   // best guess in J so reviewer has a starting point
      confidence: ambigText,        // full detail in K
      score:      best.score,
    };
  }

  // ── High or Low ───────────────────────────────────────────────────────────
  return {
    canonical:  best.canonical,
    confidence: best.score >= CONFIG.thresholdHigh ? "High" : "Low",
    score:      best.score,
  };
}

// ── Levenshtein similarity (normalized, two-row iterative) ───────────────────

function similarity(a, b) {
  if (a === b) return 1.0;
  if (!a || !b) return 0.0;
  return 1 - levenshtein(a, b) / Math.max(a.length, b.length);
}

function levenshtein(a, b) {
  const m = a.length;
  const n = b.length;
  let prev = Array.from({ length: n + 1 }, (_, j) => j);
  let curr = new Array(n + 1);

  for (let i = 1; i <= m; i++) {
    curr[0] = i;
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      curr[j] = Math.min(
        curr[j - 1] + 1,
        prev[j] + 1,
        prev[j - 1] + cost
      );
    }
    [prev, curr] = [curr, prev];
  }
  return prev[n];
}
```

